import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { format } from "prettier";
import { materialRecipes } from "../packages/tokens/src/materials.ts";
import { shapePresets } from "../packages/tokens/src/shapes.ts";
import { personalityPresets } from "../packages/tokens/src/personalities.ts";

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const header =
  "/* Generated by scripts/generate-materials.mjs. Do not edit. */\n";
const scope = ":root, .dixy-theme";
const shapes = `${header}@layer dixy.tokens {
  ${scope} {
    --dixy-shape-control: var(--dixy-radius-control);
    --dixy-shape-container: var(--dixy-radius-card);
    --dixy-shape-feature: var(--dixy-radius-24);
    --dixy-personality-press-distance: 1px;
  }
  ${Object.entries(shapePresets)
    .map(
      ([name, roles]) =>
        `[data-dixy-shape="${name}"] { ${Object.entries(roles)
          .map(
            ([role, token]) =>
              `--dixy-shape-${role}: var(--dixy-radius-${name === "rounded" && role !== "feature" ? (role === "control" ? "control" : "card") : token});`,
          )
          .join("\n")} }`,
    )
    .join("\n")}
  ${Object.entries(personalityPresets)
    .map(
      ([name, preset]) =>
        `[data-personality="${name}"] { --dixy-personality-press-distance: ${preset.pressDistance}px; }`,
    )
    .join("\n")}
}
@layer dixy.components {
  .dixy-box { box-sizing: border-box; min-inline-size: 0; border-radius: var(--dixy-shape-container); }
  .dixy-button[data-dixy-shape]:not([data-dixy-shape="rounded"]) { border-radius: var(--dixy-shape-control); }
  .dixy-shape { display: inline-block; inline-size: 5rem; block-size: 5rem; flex: none; overflow: visible; }
}`;
const tokens = `${header}@layer dixy.tokens {
  :root { ${Object.entries(materialRecipes)
    .map(
      ([name, recipe]) =>
        `--dixy-material-${name}-image: ${recipe.image};\n--dixy-material-${name}-edge: ${recipe.edge};\n--dixy-material-${name}-blend: ${recipe.blend};`,
    )
    .join("\n")} }
  ${Object.entries(materialRecipes)
    .filter(([, recipe]) => recipe.dark)
    .map(
      ([name, recipe]) =>
        `[data-appearance="light"] { --dixy-material-${name}-image: ${recipe.image}; --dixy-material-${name}-edge: ${recipe.edge}; --dixy-material-${name}-blend: ${recipe.blend}; }
  [data-appearance="dark"] { --dixy-material-${name}-image: ${recipe.dark.image}; --dixy-material-${name}-edge: ${recipe.dark.edge}; --dixy-material-${name}-blend: ${recipe.dark.blend}; }`,
    )
    .join("\n")}
}`;
const button =
  '.dixy-button[data-material]:is([data-variant="solid"], [data-variant="soft"]):not([data-disabled])';
const familySurfaces =
  ".dixy-card, .dixy-alert, .dixy-badge, .dixy-chip, .dixy-textarea, .dixy-native-select, .dixy-input-group, .dixy-list-box, .dixy-calendar, .dixy-range-calendar, .dixy-input, .dixy-select-trigger, .dixy-combobox-input-group, .dixy-autocomplete-input-group, .dixy-avatar-root, .dixy-toggle, .dixy-select-popup, .dixy-combobox-popup, .dixy-autocomplete-popup, .dixy-dialog-popup, .dixy-alert-dialog-popup, .dixy-drawer-popup, .dixy-popover-popup, .dixy-preview-card-popup, .dixy-tooltip-popup, .dixy-menu-popup, .dixy-context-menu-popup, .dixy-navigation-menu-popup, .dixy-toast-root";
const material = `${header}@layer dixy.components {
  .dixy-box[data-material] {
    background-color: var(--dixy-color-background-surface-raised);
    color: var(--dixy-color-text-primary);
    border: var(--dixy-border-default);
  }
  ${Object.entries(materialRecipes)
    .map(
      ([
        name,
        recipe,
      ]) => `:is(.dixy-box[data-material="${name}"], ${button.replace("[data-material]", `[data-material="${name}"]`)}) {
    background-image: var(--dixy-material-${name}-image); background-blend-mode: var(--dixy-material-${name}-blend);
    box-shadow: ${recipe.depth === "none" ? `var(--dixy-material-${name}-edge)` : `var(--dixy-shadow-raised)`};
  }
  .dixy-switch-root[data-material="${name}"]:not([data-disabled])::before,
  .dixy-checkbox-root[data-material="${name}"]:not([data-disabled])::before {
    background-image: var(--dixy-material-${name}-image); background-blend-mode: var(--dixy-material-${name}-blend);
    box-shadow: var(--dixy-material-${name}-edge);
  }
  :is(${familySurfaces})[data-dixy-visual][data-material="${name}"]:not([data-disabled]):not([data-pressed="false"]) {
    background-image: var(--dixy-material-${name}-image); background-blend-mode: var(--dixy-material-${name}-blend);
    box-shadow: var(--dixy-material-${name}-edge);
  }
  /* A card's finish must not erase its independent elevation token. */
  .dixy-card[data-dixy-visual][data-material="${name}"]:not([data-disabled]):not([data-pressed="false"]) {
    box-shadow: var(--dixy-card-shadow);
  }
  .dixy-toggle[data-material="${name}"][data-pressed]:is([data-variant="solid"],[data-variant="soft"]):not([data-disabled]) { background-image: var(--dixy-material-${name}-image); background-blend-mode: var(--dixy-material-${name}-blend); box-shadow: var(--dixy-material-${name}-edge); }
  .dixy-radio-root[data-material="${name}"]:not([data-disabled])::before,
  :is(.dixy-progress-root,.dixy-meter-root,.dixy-slider-root)[data-material="${name}"]:not([data-disabled]) :is(.dixy-progress-indicator,.dixy-meter-indicator,.dixy-slider-indicator),
  .dixy-number-field-root[data-material="${name}"]:not([data-disabled]) .dixy-number-field-group,
  .dixy-otp-field-root[data-material="${name}"]:not([data-disabled]) .dixy-otp-field-input {
    background-image: var(--dixy-material-${name}-image); background-blend-mode: var(--dixy-material-${name}-blend);
    box-shadow: var(--dixy-material-${name}-edge);
  }
  .dixy-tabs-indicator[data-material="${name}"]:not([data-variant="line"]) {
    background-image: var(--dixy-material-${name}-image); background-blend-mode: var(--dixy-material-${name}-blend);
    box-shadow: var(--dixy-material-${name}-edge);
  }`,
    )
    .join("\n")}
  /* Glossy keeps its enamel as two thin bands; other finishes cover the whole button. */
  ${button.replace("[data-material]", '[data-material="glossy"]')} { background-size: 100% 3px; background-repeat: no-repeat; background-position: top, bottom; }
  [data-effects="reduced"] :is([data-dixy-visual],.dixy-progress-indicator,.dixy-meter-indicator,.dixy-slider-indicator,.dixy-number-field-group,.dixy-otp-field-input) { background-image: none !important; box-shadow: none !important; }
  [data-effects="reduced"] .dixy-radio-root::before { background-image: none !important; box-shadow: none !important; }
  [data-effects="reduced"] .dixy-tabs-indicator { background-image: none !important; box-shadow: none !important; }
  [data-effects="reduced"] :is(.dixy-box, .dixy-button)[data-material] { background-image: none !important; box-shadow: none !important; }
  [data-effects="reduced"] :is(.dixy-switch-root, .dixy-checkbox-root)[data-material]::before { background-image: none !important; box-shadow: none !important; }
  @media (prefers-reduced-transparency: reduce), (prefers-contrast: more), (forced-colors: active) {
    :is([data-dixy-visual],.dixy-progress-indicator,.dixy-meter-indicator,.dixy-slider-indicator,.dixy-number-field-group,.dixy-otp-field-input) { background-image: none !important; box-shadow: none !important; }
    .dixy-radio-root::before { background-image: none !important; box-shadow: none !important; }
    .dixy-tabs-indicator { background-image: none !important; box-shadow: none !important; }
    :is(.dixy-box, .dixy-button)[data-material] { background-image: none !important; box-shadow: none !important; }
    :is(.dixy-switch-root, .dixy-checkbox-root)[data-material]::before { background-image: none !important; box-shadow: none !important; }
  }
}`;
const backdrop = `${header}@layer dixy.components {
  /* Experimental, bounded toolbar. Critical text sits on its own opaque backing. */
  .dixy-backdrop-pilot { background: var(--dixy-color-background-surface-raised); border: var(--dixy-border-default); border-radius: var(--dixy-radius-full); }
  .dixy-backdrop-pilot > * { background-color: var(--dixy-color-background-surface-raised); color: var(--dixy-color-text-primary); border-radius: inherit; }
  @supports ((backdrop-filter: blur(8px)) or (-webkit-backdrop-filter: blur(8px))) {
    [data-effects="backdrop"] .dixy-backdrop-pilot {
      background: color-mix(in srgb, var(--dixy-color-background-surface-raised) 75%, transparent);
      -webkit-backdrop-filter: blur(8px);
      backdrop-filter: blur(8px);
    }
  }
  [data-effects="reduced"] .dixy-backdrop-pilot { background: var(--dixy-color-background-surface-raised) !important; -webkit-backdrop-filter: none !important; backdrop-filter: none !important; }
  @media (prefers-reduced-transparency: reduce), (prefers-contrast: more), (forced-colors: active) {
    .dixy-backdrop-pilot { background: var(--dixy-color-background-surface-raised) !important; -webkit-backdrop-filter: none !important; backdrop-filter: none !important; }
  }
}`;
const outputs = {
  "packages/tokens/src/shapes.css": shapes,
  "packages/tokens/src/materials.css": tokens,
  "packages/react/src/styles/materials.css": tokens + material,
  "packages/react/src/styles/backdrop-pilot.css": backdrop,
};
if (process.argv.includes("--dist")) {
  for (const name of ["shapes", "materials"])
    outputs[`packages/tokens/dist/${name}.css`] =
      outputs[`packages/tokens/src/${name}.css`];
}
for (const [file, raw] of Object.entries(outputs)) {
  const content = await format(raw, { parser: "css" });
  const target = path.join(root, file);
  const current = fs.existsSync(target) ? fs.readFileSync(target, "utf8") : "";
  if (process.argv.includes("--check")) {
    if (content !== current)
      throw new Error(`${file} is stale. Run pnpm tokens:generate.`);
  } else if (content !== current) {
    fs.mkdirSync(path.dirname(target), { recursive: true });
    fs.writeFileSync(target, content);
  }
}
console.log(
  process.argv.includes("--check")
    ? "Material and shape CSS matches canonical contracts."
    : "Generated material and shape CSS.",
);
